B.b6E=new A.a_("3. TAXA DE SERVI\xc7O & REPASSE",null,B.dW,null,null,null,null,null,null,null,null,null,null)
B.b7o=new A.a_("A plataforma ret\xe9m uma taxa de intermedia\xe7\xe3o e seguran\xe7a de 10% sobre o valor total do chamado, repassando 90% l\xedquido ao prestador do atendimento.",null,B.es,null,null,null,null,null,null,null,null,null,null)
B.b61=new A.a_("4. PRAZOS E PONTUALIDADE",null,B.dW,null,null,null,null,null,null,null,null,null,null)
B.b7_=new A.a_("O prestador deve cumprir os prazos de deslocamento:\n\u2022 At\xe9 1 km de dist\xe2ncia: chegada em at\xe9 30 minutos.\n\u2022 Acima de 1 km: chegada em at\xe9 1 hora.\nO n\xe3o comparecimento sem justificativa enseja penalidades e cancelamento do chamado.",null,B.es,null,null,null,null,null,null,null,null,null,null)
B.Wx=new A.y(!0,B.L,null,null,null,null,13,B.x,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null)
B.b5r=new A.a_("5. CANAL SEGURO & PROIBI\xc7\xc3O DE INTERMEDIA\xc7\xc3O EXTERNA",null,B.Wx,null,null,null,null,null,null,null,null,null,null)
B.b8e=new A.a_("\xc9 estritamente proibido trocar contatos externos (n\xfameros de telefone, WhatsApp particular, chaves PIX externas ou redes sociais) pelo chat do aplicativo com o objetivo de negociar fora da plataforma. A infra\xe7\xe3o acarreta o bloqueio imediato e banimento definitivo das contas envolvidas.",null,B.es,null,null,null,null,null,null,null,null,null,null)
B.b5N=new A.a_("6. AVALIA\xc7\xd5ES E CONDUTA",null,B.dW,null,null,null,null,null,null,null,null,null,null)
B.b8j=new A.a_("Todas as partes concordam em agir com respeito m\xfatuo, integridade e profissionalismo. Ao fim de cada atendimento, o cliente realiza a avalia\xe7\xe3o de 1 a 5 estrelas que comp\xf5e a pontua\xe7\xe3o p\xfablica do profissional.",null,B.es,null,null,null,null,null,null,null,null,null,null)
